import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"43、【夬】 乾下兑上","description":"温公易说 - 43、【夬】 乾下兑上","frontmatter":{"title":"43、【夬】 乾下兑上","description":"温公易说 - 43、【夬】 乾下兑上"},"headers":[],"relativePath":"zh/classics/wengong/044.md","filePath":"zh/classics/wengong/044.md"}'),n={name:"zh/classics/wengong/044.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_43、【夬】-乾下兑上" tabindex="-1">43、【夬】 乾下兑上 <a class="header-anchor" href="#_43、【夬】-乾下兑上" aria-label="Permalink to “43、【夬】 乾下兑上”">​</a></h1><h3 id="彖曰-夬-决也。刚决柔也-健而说。决而和-扬于王庭-柔乘五刚也。孚号有厉-其危乃光也。告自邑-不利即戎-所尚乃穷也。利有攸往-刚长乃终也。" tabindex="-1">彖曰：夬，决也。刚决柔也，健而说。决而和，扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。 <a class="header-anchor" href="#彖曰-夬-决也。刚决柔也-健而说。决而和-扬于王庭-柔乘五刚也。孚号有厉-其危乃光也。告自邑-不利即戎-所尚乃穷也。利有攸往-刚长乃终也。" aria-label="Permalink to “彖曰：夬，决也。刚决柔也，健而说。决而和，扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。”">​</a></h3><h3 id="象曰-泽上于天-夬。君子以施禄及下-居德则忌。" tabindex="-1">象曰：泽上于天，夬。君子以施禄及下，居德则忌。 <a class="header-anchor" href="#象曰-泽上于天-夬。君子以施禄及下-居德则忌。" aria-label="Permalink to “象曰：泽上于天，夬。君子以施禄及下，居德则忌。”">​</a></h3><h3 id="初九-壮于前趾-往不胜为咎-象曰-不胜而往-咎也。" tabindex="-1">初九：壮于前趾，往不胜为咎 象曰：不胜而往，咎也。 <a class="header-anchor" href="#初九-壮于前趾-往不胜为咎-象曰-不胜而往-咎也。" aria-label="Permalink to “初九：壮于前趾，往不胜为咎 象曰：不胜而往，咎也。”">​</a></h3><h3 id="九二-惕号-莫夜有戎-勿恤-象曰-有戎勿恤-得中道也。" tabindex="-1">九二：惕号，莫夜有戎，勿恤 象曰：有戎勿恤，得中道也。 <a class="header-anchor" href="#九二-惕号-莫夜有戎-勿恤-象曰-有戎勿恤-得中道也。" aria-label="Permalink to “九二：惕号，莫夜有戎，勿恤 象曰：有戎勿恤，得中道也。”">​</a></h3><h3 id="九三-壮于頄-有凶。君子夬夬-独行遇雨若濡-有愠无咎-象曰-君子夬夬-终无咎也。" tabindex="-1">九三：壮于頄，有凶。君子夬夬，独行遇雨若濡，有愠无咎 象曰：君子夬夬，终无咎也。 <a class="header-anchor" href="#九三-壮于頄-有凶。君子夬夬-独行遇雨若濡-有愠无咎-象曰-君子夬夬-终无咎也。" aria-label="Permalink to “九三：壮于頄，有凶。君子夬夬，独行遇雨若濡，有愠无咎 象曰：君子夬夬，终无咎也。”">​</a></h3><p>壮于頄，壮形于面也。三为健极，故曰壮于頄也。物恶太健，故有凶。然君子居之，体刚履正，决决无疑，信志独行而不易于世，故虽怨怒不足为咎也。雨濡者，怨谤之象也。</p><h3 id="九四-臀无肤-其行次且。牵羊悔亡-闻言不信-象曰-其行次且-位不当也。闻言不信-聪不明也。" tabindex="-1">九四：臀无肤，其行次且。牵羊悔亡，闻言不信 象曰：其行次且，位不当也。闻言不信，聪不明也。 <a class="header-anchor" href="#九四-臀无肤-其行次且。牵羊悔亡-闻言不信-象曰-其行次且-位不当也。闻言不信-聪不明也。" aria-label="Permalink to “九四：臀无肤，其行次且。牵羊悔亡，闻言不信 象曰：其行次且，位不当也。闻言不信，聪不明也。”">​</a></h3><h3 id="九五-苋陆夬夬-中行无咎-象曰-中行无咎-中未光也。" tabindex="-1">九五：苋陆夬夬，中行无咎 象曰：中行无咎，中未光也。 <a class="header-anchor" href="#九五-苋陆夬夬-中行无咎-象曰-中行无咎-中未光也。" aria-label="Permalink to “九五：苋陆夬夬，中行无咎 象曰：中行无咎，中未光也。”">​</a></h3><h3 id="上六-无号-终有凶-象曰-无号之凶-终不可长也。" tabindex="-1">上六：无号，终有凶 象曰：无号之凶，终不可长也。 <a class="header-anchor" href="#上六-无号-终有凶-象曰-无号之凶-终不可长也。" aria-label="Permalink to “上六：无号，终有凶 象曰：无号之凶，终不可长也。”">​</a></h3>',10)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
